mapper.select:
SELECT ev.*, ea.asset_name, emp.unit, emp.alarm_upper, emp.alarm_lower, emp.point_name FROM environment_value ev LEFT JOIN equipment_assets ea ON ea.asset_id = ev.asset_id LEFT JOIN environment_monitor_point emp ON emp.point_code = ev.monitor_point_code WHERE 1=1
AND ev.date_type = #{data.dateType}
AND emp.point_name LIKE CONCAT('%', #{data.monitorPointName}, '%')
AND ev.monitor_point_code = #{data.monitorPointCode}
AND ev.monitor_time > #{data.startTime}
AND ev.monitor_time < #{data.endTime}
